const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');const C=require('../scripts/group-chat-core.js');const {JSDOM,VirtualConsole}=require('./helpers/jsdom.cjs'),root=path.join(__dirname,'..');const flush=async()=>{for(let i=0;i<12;i++)await new Promise(r=>setImmediate(r))};
function fixture(){const state={users:[{name:'用户甲'},{name:'用户乙'}],characters:[{name:'角色甲',details:'甲的人设',chatSettings:{userIndex:0}},{name:'角色乙',details:'乙的人设',chatSettings:{userIndex:0}},{name:'角色丙',chatSettings:{userIndex:0}},{name:'他人角色',chatSettings:{userIndex:1}},{name:'助手',builtinRole:'iris-assistant',chatSettings:{userIndex:0}}],messages:{'0-0-chat':[{mine:true,text:'绝不能进入群聊的私聊秘密'}]}};state.users.forEach(u=>C.identity(u,'user'));state.characters.forEach(r=>C.identity(r,'role'));return state}
function boot(){const errors=[],snapshots=[],calls=[],saved=fixture();let responder=async()=>{throw Error('未配置模拟回复')};Object.assign(saved,{char:0,user:0,offline:false,irisWelcomeChoice:'not-needed',irisGuideOrbHidden:true,settings:{}});const html=fs.readFileSync(path.join(root,'index.html'),'utf8').replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,'');let fail=false;const dom=new JSDOM(html,{runScripts:'dangerously',url:'http://localhost/',pretendToBeVisual:true,virtualConsole:new VirtualConsole(),beforeParse(w){w.IRIS_BOOT_STATE=saved;w.IRIS_STYLES_READY=Promise.resolve();w.fetch=async(url,init)=>{if(init?.method==='POST'){calls.push(JSON.parse(init.body));const data=await responder(JSON.parse(init.body));return{ok:true,headers:{get:()=> 'application/json'},json:async()=>({choices:[{message:{content:JSON.stringify(data)}}]})}}return String(url).startsWith('assets/earth-cities.json')?{ok:true,json:async()=>JSON.parse(fs.readFileSync(path.join(root,'assets/earth-cities.json'),'utf8'))}:Promise.reject(Error('external network disabled'))};w.matchMedia=()=>({matches:false,addEventListener(){},removeEventListener(){}});w.confirm=()=>true;w.scrollTo=()=>{};w.HTMLDialogElement.prototype.showModal=function(){this.open=true};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'))};w.IrisStorage={mode:'test',save:async value=>{if(fail)throw Error('模拟存储失败');snapshots.push(structuredClone(value))}};w.addEventListener('error',event=>errors.push(event.error?.stack||event.message))}});const scripts=JSON.parse(fs.readFileSync(path.join(root,'scripts/storage-bootstrap.js'),'utf8').match(/const scripts = (\[[^\n]+\]);/)[1].replace(/'/g,'"'));for(const file of scripts){const tag=dom.window.document.createElement('script');Object.defineProperty(tag,'src',{value:'http://localhost/'+file});tag.textContent=fs.readFileSync(path.join(root,file),'utf8');dom.window.document.body.append(tag)}return{w:dom.window,errors,snapshots,calls,respond:fn=>{responder=fn},fail:value=>{fail=value}}}

const settled=async w=>{for(let i=0;i<100;i++){await flush();if(!w.document.querySelector('.novel-feedback.is-busy'))return;await new Promise(r=>setTimeout(r,10))}throw Error('UI没有完成：'+w.document.querySelector('.novel-feedback')?.textContent)};
const click=(w,action)=>{const b=w.document.querySelector('[data-n-action="'+action+'"]');assert.ok(b,action);b.click()};
const audienceReply=()=>({reviews:[1,2,3,4,5].map(i=>({name:'观众'+i,score:i%5+1,text:'本集根据具体剧情留下的评价'+i})),comments:[{cueIndex:0,text:'开场这一句值得细看',color:'cyan'}]});
const audienceSettled=async w=>{for(let i=0;i<150;i++){await flush();if(w.eval('IrisNovelCore.normalize(state).projects.every(p=>p.status!=="released"||(p.screen?.episodes||[]).every(ep=>!IrisNovelScreenCore.isPublished(p,ep)||ep.reviews?.length))'))return;await new Promise(r=>setTimeout(r,5))}throw Error('观众评价未完成')};
function filmChapters(){return [1,2,3].map(n=>({title:'原著第'+n+'章',content:Array.from({length:24},(_,i)=>'角色甲在第'+n+'章核对第'+i+'份原始记录，发现日期与交接人写得十分清楚。她将记录放回桌上，继续确认事情的实际经过。').join('\n')}))}
function episodeReply(source){const cues=source.flatMap(c=>c.content.split(/\n+/).map((text,i)=>({chapterId:c.id,kind:i===0?'dialogue':'action',partId:'',character:'角色甲',text,sourceQuote:text,location:''})));return{title:'按原著拍摄',cues,comments:[{cueIndex:0,text:'细节终于对上了',color:'rose'},{cueIndex:3,text:'等这段很久了',color:'cyan'}]}}
function open(w){w.eval("state.settings.apiConfigs=[{id:'novel-api',url:'https://example.test/v1',key:'test',model:'test',models:['test'],temperature:0.6}];state.settings.activeApiConfigId='novel-api';openFeaturePage('novels')");}
test('homepage entry opens book store, reading, writing, identity isolation and preserves editor drafts on storage failures',async()=>{const f=boot(),w=f.w;try{assert.ok(w.document.querySelector('[data-dock-feature="novels"]'));open(w);assert.equal(w.document.querySelectorAll('.novel-book-row').length,12);w.document.querySelector('[data-n-book]').click();click(w,'read');assert.ok(w.document.querySelector('.novel-reader>p'));w.document.querySelector('#featureBack').click();w.document.querySelector('#featureBack').click();w.document.querySelector('[data-n-tab="works"]').click();click(w,'new-book');const form=w.document.querySelector('[data-n-editor]');assert.equal(form.elements.content,undefined);assert.equal(form.elements.chapterTitle,undefined);assert.equal(w.document.querySelector('[data-n-action="back"]'),null);for(const [key,value] of Object.entries({title:'我的爽文',synopsis:'我的原创简介',genre:'重生逆袭'}))form.elements[key].value=value;form.dispatchEvent(new w.Event('input',{bubbles:true}));f.fail(true);form.requestSubmit();await settled(w);assert.ok(w.document.querySelector('[data-n-editor]'));assert.equal(w.document.querySelector('[name="synopsis"]').value,'我的原创简介');f.fail(false);w.document.querySelector('[data-n-editor]').requestSubmit();await settled(w);assert.ok(w.document.querySelector('.novel-detail-head'),w.document.querySelector('.novel-feedback')?.textContent);assert.match(w.document.querySelector('.novel-detail-head').textContent,/我的爽文/);assert.equal(w.document.querySelectorAll('.novel-chapter-entry').length,0);click(w,'new-chapter');const chapterForm=w.document.querySelector('[data-n-editor]');chapterForm.elements.chapterTitle.value='第一章';chapterForm.elements.content.value='我自己的正文';chapterForm.requestSubmit();await settled(w);assert.equal(w.document.querySelectorAll('.novel-chapter-entry').length,1);click(w,'publish');await settled(w);w.document.querySelector('#featureBack').click();const select=w.document.querySelector('[data-n-persona]');select.value='1';select.dispatchEvent(new w.Event('change'));w.document.querySelector('[data-n-tab="works"]').click();assert.equal(w.document.querySelectorAll('.novel-book-row').length,0);assert.deepEqual(f.errors,[])}finally{w.IrisNovelScreen?.unmount();await flush();w.close()}});

test('actual short-drama UI posts a linked group card and finishes single-batch casting, auditions, consent, filming and wallet payments',async()=>{const f=boot(),w=f.w;try{open(w);w.eval(`{IrisMarketCore.normalize(state);const d=IrisGroupChatCore.clone(IrisGroupChatCore.store(state));IrisGroupChatCore.create(state,d,{userIndex:0,roleIds:state.characters.slice(0,2).map(r=>r.irisGroupId),name:'试戏群'});state.groupChats=d;const s=IrisNovelCore.normalize(state),b=IrisNovelCore.createBook(s,{title:'我的试戏故事',genre:'重生逆袭',author:'我',synopsis:'逆袭爽文',chapters:${JSON.stringify(filmChapters())}});IrisNovelCore.publish(s,b.id);}`);w.document.querySelector('[data-n-tab="works"]').click();w.document.querySelector('[data-n-book]').click();f.respond(async()=>({offers:[{company:'星页影业',direction:'重生逆袭，身份反转',fee:1000,budget:100000,episodes:3,days:7,parts:[{name:'女主',description:'外柔内刚',fee:10000,slots:3,scene:'面对质疑宣布身份'},{name:'男主',description:'沉稳克制',fee:8000,slots:3,scene:'谈判中做出选择'}]}]}));click(w,'offers');await settled(w);assert.equal(f.calls.length,1);const start=w.eval('IrisMarketCore.persona(state,0).wallet.balanceCents');click(w,'offer-detail');assert.match(w.document.querySelector('.novel-contract-paper').textContent,/版权报价/);click(w,'accept-offer');await settled(w);assert.equal(w.eval('IrisMarketCore.persona(state,0).wallet.balanceCents'),start+100000);const select=w.document.querySelector('[data-n-group]');select.selectedIndex=1;f.respond(async()=>w.eval(`(()=>{const p=IrisNovelCore.normalize(state).projects[0];return{decisions:state.characters.slice(0,2).map((r,i)=>({actorId:r.irisGroupId,action:'apply',partId:p.parts[i].id,responseMs:1000+i,reason:i?'喜欢这个人物':'想挑战一种不同的生活，不是为了钱'}))}})()`));click(w,'post-casting');await settled(w);for(let i=0;i<80&&w.eval('IrisNovelStudio.recruitmentPending(state.groupChats.items[0])');i++){await flush();await new Promise(r=>setTimeout(r,5))}assert.equal(f.calls.length,2);assert.equal(w.eval('IrisNovelCore.normalize(state).projects[0].responsesDone'),true);assert.equal(w.eval('state.groupChats.items[0].messages.filter(m=>m.type==="studio-casting").length'),1);await flush();assert.ok(w.document.querySelector('.group-chat-thread'));assert.ok(w.document.querySelector('[data-studio-open]'));assert.equal(w.document.querySelectorAll('.studio-casting-roles>div').length,2);assert.match(w.document.querySelector('.studio-casting-card').textContent,/星页影业.*我的试戏故事.*全剧片酬/);assert.equal(w.document.querySelectorAll('.studio-casting-card').length,1);w.document.querySelector('[data-studio-open]').click();await settled(w);assert.ok(w.document.querySelector('.novel-project-head'));const self=w.document.querySelector('[data-n-apply]');self.elements.partId.selectedIndex=0;self.requestSubmit();await settled(w);assert.ok(w.document.querySelector('.group-chat-thread'));w.document.querySelector('[data-studio-open]').click();await settled(w);assert.equal(f.calls.length,2);click(w,'audition-start');await settled(w);const form=w.document.querySelector('[data-n-self-audition]');form.elements.performance.value='我放下合同，停顿片刻，平静地念出自己的名字。';form.requestSubmit();await settled(w);f.respond(async()=>w.eval(`({auditions:IrisNovelCore.normalize(state).projects[0].applicants.filter(a=>a.accepted&&!a.user).map(a=>({actorId:a.actorId,performance:'演出的台词与动作。',score:72,review:'停顿准确，目光转移略显生硬。',strength:'台词',weakness:'走位'}))})`));click(w,'auditions');await settled(w);assert.equal(f.calls.length,3);f.respond(async()=>w.eval(`(()=>{const p=IrisNovelCore.normalize(state).projects[0];return{cast:p.parts.map((r,i)=>({partId:r.id,actorId:i?state.characters[1].irisGroupId:'user:'+state.users[0].irisMarketId,reason:'通过实际试镜适配'})),note:'这组搭档符合改编方向'}})()`));click(w,'cast');await settled(w);f.respond(async()=>w.eval(`({decisions:[{actorId:state.characters[1].irisGroupId,accept:true,reason:'档期可以安排，我愿意尝试'}]})`));click(w,'contracts');await settled(w);click(w,'user-sign');await settled(w);click(w,'start');await settled(w);assert.equal(w.eval('IrisNovelCore.normalize(state).projects[0].status'),'filming');click(w,'screen-show');for(let i=0;i<3;i++){f.respond(async payload=>payload.messages[0].content.includes('80 至 100 条')?w.eval(`(()=>{const ep=IrisNovelCore.normalize(state).projects[0].screen.episodes.at(-1);return{comments:Array.from({length:80},(_,i)=>({cueIndex:i%ep.cues.length,text:'看到这一段的反应'+i,color:['rose','cyan','amber'][i%3]}))}})()`):episodeReply(w.eval('IrisNovelScreenCore.sources(IrisNovelCore.normalize(state).projects[0],10).chapters')));if(i)w.document.querySelector('[data-screen-episode="'+i+'"]').click();click(w,'screen-generate');await settled(w)}f.respond(async()=>audienceReply());w.document.querySelector('[data-screen-tab="production"]').click();assert.equal(w.eval('IrisNovelCore.normalize(state).projects[0].status'),'finished');click(w,'release');await settled(w);await audienceSettled(w);assert.equal(w.eval('IrisNovelCore.normalize(state).projects[0].status'),'released');assert.equal(w.eval('IrisMarketCore.persona(state,0).wallet.balanceCents'),start+100000+w.eval('IrisNovelCore.normalize(state).projects[0].parts[0].feeCents'));assert.equal(w.eval('IrisMarketCore.persona(state,0).ledger.filter(r=>r.studioPaymentId).length'),3);assert.equal(f.calls.length,11);assert.ok(f.calls.every(c=>c.temperature===0.6));assert.ok(w.eval('state.groupChats.items[0].messages.some(m=>m.text.includes("正式上线"))'));assert.deepEqual(f.errors,[])}finally{w.IrisNovelScreen?.unmount();await flush();w.close()}});

