test('auto audition saves a user performance and expanded progress stays in the scrolling area',async()=>{const f=boot(),w=f.w;try{open(w);w.eval(`{const data=IrisGroupChatCore.clone(IrisGroupChatCore.store(state)),group=IrisGroupChatCore.create(state,data,{userIndex:0,roleIds:chars.slice(0,2).map(r=>r.irisGroupId),name:'试镜群'});state.groupChats=data;const s=IrisNovelCore.normalize(state),b=s.books[0];IrisNovelCore.makeOffers(s,b.id,{offers:[{company:'制作公司',direction:'原著改编',fee:1000,budget:300000,episodes:3,days:7,parts:[{name:'主角',description:'沉稳',fee:80000,scene:'面对质疑说出真相'},{name:'配角',description:'冷静',fee:50000,scene:'核对文件并提出疑问'}]}]});const p=IrisNovelCore.acceptOffer(s,b.id,b.offers[0].id);IrisNovelCore.linkGroup(s,p.id,group.id);IrisNovelCore.apply(s,p.id,'user:'+state.users[0].irisMarketId,'用户甲',p.parts[0].id,{user:true});IrisNovelCore.applications(s,p.id,{decisions:chars.slice(0,2).map(r=>({actorId:r.irisGroupId,action:'decline',reason:'档期不合适'}))},chars.slice(0,2).map(r=>({id:r.irisGroupId,name:r.name})));IrisNovelCore.beginAuditions(s,p.id);openNovelStudioProject(p.id,state.users[0].irisMarketId)}`);const d=w.document,progress=d.querySelector('.novel-project-progress-panel');assert.ok(progress);assert.ok(d.querySelector('.novel-scroll').contains(progress));assert.equal(d.querySelector('.novel-project-fixed').contains(progress),false);progress.open=true;assert.ok(d.querySelector('[data-n-action="auto-self-audition"]'));assert.ok(d.querySelector('[data-n-self-audition]'));f.respond(async()=>({performance:'我站在众人面前，先看一眼桌上的旧文件，再抬头望向质疑我的人。停顿片刻后，我把事实逐一说清。声音起初有些紧，随后逐渐稳定。我把文件放回桌上，等待对方回答。对方沉默时，我轻轻呼吸，重新核对日期与签名，再用平稳的语气补充那天发生的细节。'}));click(w,'auto-self-audition');await settled(w);assert.equal(f.calls.length,1);assert.match(w.eval('IrisNovelCore.normalize(state).projects[0].auditions.find(a=>a.user).performance'),/我站在众人面前/);assert.equal(d.querySelector('[data-n-action="auto-self-audition"]'),null);assert.deepEqual(f.errors,[])}finally{w.IrisNovelScreen?.unmount();await flush();w.close()}});

test('pending novel quotation allows another page and concurrent API, then saves to its original persona',async()=>{const f=boot(),w=f.w;try{open(w);const bookId=w.document.querySelector('[data-n-book]').dataset.nBook;w.document.querySelector('[data-n-book]').click();let finish;f.respond(async()=>new Promise(resolve=>{finish=resolve}));click(w,'offers');for(let i=0;i<50&&!finish;i++)await flush();assert.ok(finish);w.openFeaturePage('worldbook');assert.ok(w.document.querySelector('#featurePageContent'));w.eval('state.user=1');f.respond(async()=>({reply:'另一个页面的接口已完成'}));const other=w.eval("requestConfiguredChatCompletion(state.settings.apiConfigs[0],'test','另一个页面的请求',[],'worldbook',true)");await other;assert.equal(f.calls.length,2);finish({offers:[{company:'原用户公司',direction:'忠于原著',companyStatus:{funding:3,production:4,distribution:2,summary:'擅长人物戏',risk:'发行渠道有限'},fee:1000,budget:300000,episodes:3,days:7,parts:[{name:'主角',description:'沉稳',fee:80000,scene:'对话'},{name:'配角',description:'冷静',fee:50000,scene:'核对'}]}]});await flush();assert.equal(w.eval(`IrisNovelCore.book(IrisNovelCore.normalize(state,0),${JSON.stringify(bookId)}).offers?.[0]?.company`),'原用户公司');assert.equal(w.eval('IrisNovelCore.normalize(state,1).books.some(b=>b.offers?.length)'),false);assert.match(w.document.querySelector('#featurePageContent').textContent,/世界书|World Book/i);assert.deepEqual(f.errors,[])}finally{w.IrisNovelScreen?.unmount();await flush();w.close()}});

test('manual character planning saves a colored relationship map and discarding an edit preserves the saved identities',async()=>{const f=boot(),w=f.w;try{open(w);w.document.querySelector('[data-n-tab="works"]').click();click(w,'new-book');const form=w.document.querySelector('[data-n-editor]');for(const [key,value] of Object.entries({title:'雾港',genre:'都市悬疑',synopsis:'旧友一起追查失踪案。',premise:'现代港口城市。'}))form.elements[key].value=value;form.dispatchEvent(new w.Event('input',{bubbles:true}));const editPerson=(key,value)=>{const input=w.document.querySelector('[data-story-person][data-story-field="'+key+'"]');input.value=value;input.dispatchEvent(new w.Event('input',{bubbles:true}));input.dispatchEvent(new w.Event('change',{bubbles:true}))};click(w,'story-person-add');editPerson('name','沈青');editPerson('identity','女主，调查记者。');editPerson('role','heroine');click(w,'story-person-add');editPerson('name','江宁');editPerson('identity','女主的律师朋友。');editPerson('role','support');click(w,'story-relation-add');assert.equal(w.document.querySelectorAll('.novel-relationship-map line').length,1);assert.equal(w.document.querySelectorAll('.novel-story-node[data-tone="lead"]').length,1);assert.equal(w.document.querySelectorAll('.novel-story-node[data-tone="support"]').length,1);w.document.querySelector('[data-n-editor]').requestSubmit();await settled(w);assert.ok(w.document.querySelector('.novel-detail-head'));assert.match(w.document.querySelector('.novel-story-identities').textContent,/律师朋友/);w.document.querySelector('[data-story-inspect]').click();assert.equal(w.document.querySelector('.novel-story-identities').open,true);assert.equal(w.document.activeElement.hasAttribute('data-story-identity'),true);assert.equal(w.eval('IrisNovelCore.normalize(state).books[0].storyRelations.length'),1);click(w,'edit-book');editPerson('identity','尚未保存的新身份');click(w,'cancel-editor');assert.match(w.document.querySelector('.novel-story-identities').textContent,/调查记者/);assert.doesNotMatch(w.document.querySelector('.novel-story-identities').textContent,/尚未保存/);click(w,'edit-book');const last=w.document.querySelectorAll('[data-story-focus]')[1];last.click();click(w,'story-person-remove');assert.equal(w.document.querySelectorAll('.novel-relationship-map line').length,0);w.document.querySelector('[data-n-editor]').requestSubmit();await settled(w);assert.equal(w.eval('IrisNovelCore.normalize(state).books[0].storyRelations.length'),0);assert.deepEqual(f.errors,[])}finally{w.close()}});

test('API character planning uses the selected genre, protects manually entered identities and passes the plan to the first chapter',async()=>{const f=boot(),w=f.w;try{open(w);w.document.querySelector('[data-n-tab="works"]').click();click(w,'new-book');const form=w.document.querySelector('[data-n-editor]');for(const [key,value] of Object.entries({title:'雾港',genre:'都市悬疑',synopsis:'记者查找姐姐失踪的真相。',premise:'现代港口城市，证据驱动。'}))form.elements[key].value=value;form.dispatchEvent(new w.Event('input',{bubbles:true}));click(w,'story-person-add');let field=w.document.querySelector('[data-story-field="name"]');field.value='沈青';field.dispatchEvent(new w.Event('input',{bubbles:true}));field=w.document.querySelector('[data-story-field="identity"]');field.value='记者，有一位失踪的姐姐。';field.dispatchEvent(new w.Event('input',{bubbles:true}));const id=w.document.querySelector('[data-story-person]').dataset.storyPerson;f.respond(async payload=>{const prompt=payload.messages[0].content;assert.match(prompt,/都市悬疑/);assert.match(prompt,/证据驱动/);return{storyCast:[{id,name:'模型擅自改名',identity:'模型改变身份',role:'lead'},{id:'friend',name:'江宁',identity:'律师，女主好友。',role:'support'},{id:'enemy',name:'陆临',identity:'港务负责人。',role:'support'},{id:'romance',name:'温予',identity:'摄影师。',role:'support'}],storyRelations:[{from:id,to:'friend',type:'connection',label:'多年相识'},{from:id,to:'enemy',type:'tension',label:'调查分歧'},{from:id,to:'romance',type:'romance',label:'互有好感'}]}});click(w,'story-characters');await settled(w);assert.equal(w.document.querySelectorAll('[data-story-focus]').length,4);assert.equal(w.document.querySelector('[data-story-field="name"]').value,'沈青');assert.match(w.document.querySelector('[data-story-field="identity"]').value,/失踪的姐姐/);assert.equal(w.document.querySelectorAll('.novel-story-node[data-tone="lead"]').length,1);assert.equal(w.document.querySelectorAll('.novel-story-node[data-tone="support"]').length,3);assert.doesNotMatch(w.document.querySelector('.novel-relationship-legend').textContent,/好友|朋友|敌人/);for(const tone of ['connection','tension','romance'])assert.ok(w.document.querySelector('svg g[data-tone="'+tone+'"]'));w.document.querySelector('[data-n-editor]').requestSubmit();await settled(w);assert.equal(w.document.querySelectorAll('.novel-chapter-entry').length,0);f.respond(async payload=>{const prompt=payload.messages[0].content;for(const text of ['都市悬疑','现代港口城市','沈青','失踪的姐姐','多年相识','调查分歧','互有好感'])assert.ok(prompt.includes(text),text);return{chapter:{title:'第一章',content:'沈青走进档案馆，江宁已经等在那里。两人决定共同核对资料，彼此仍有保留。'},relationshipUpdates:[{from:id,to:'friend',type:'cooperation',label:'共同查证，互有戒心'}]}});click(w,'continue');await settled(w);assert.match(w.document.querySelector('.novel-reader').textContent,/沈青走进档案馆/);assert.equal(f.calls.length,2);w.document.querySelector('#featureBack').click();assert.match(w.document.querySelector('.novel-relationship-map').textContent,/共同查证，互有戒心/);assert.deepEqual(f.errors,[])}finally{w.close()}});

test('an invalid generated relationship keeps the manually entered character draft intact',async()=>{const f=boot(),w=f.w;try{open(w);w.document.querySelector('[data-n-tab="works"]').click();click(w,'new-book');const form=w.document.querySelector('[data-n-editor]');form.elements.genre.value='都市悬疑';form.dispatchEvent(new w.Event('input',{bubbles:true}));click(w,'story-person-add');const field=w.document.querySelector('[data-story-field="name"]');field.value='用户自定主角';field.dispatchEvent(new w.Event('input',{bubbles:true}));const id=field.dataset.storyPerson;f.respond(async()=>({storyCast:[{id,name:'模型主角',identity:'记者',role:'lead'},{id:'b',name:'搭档',identity:'律师',role:'friend'}],storyRelations:[{from:id,to:'不存在的人物',type:'friend'}]}));click(w,'story-characters');await settled(w);assert.match(w.document.querySelector('.novel-feedback').textContent,/已有人物/);assert.equal(w.document.querySelector('[data-story-field="name"]').value,'用户自定主角');assert.equal(w.document.querySelectorAll('[data-story-focus]').length,1);assert.equal(w.eval('IrisNovelCore.normalize(state).books.filter(b=>b.owner).length'),0);assert.deepEqual(f.errors,[])}finally{w.close()}});

function filmedProject(w){w.eval(`{IrisMarketCore.normalize(state);const s=IrisNovelCore.normalize(state),b=IrisNovelCore.createBook(s,{title:'续拍检查',genre:'都市悬疑',synopsis:'按原著续拍',chapters:${JSON.stringify(filmChapters().slice(0,1))}}),p={id:'audit-film',title:b.title,bookId:b.id,company:'检查制作组',episodes:1,episodeMinutes:5,productionMode:'episodes',days:7,status:'filming',revision:0,parts:[{id:'hero',name:'原著主角',description:'原著人物',feeCents:10000}],cast:[{partId:'hero',actorId:'user:'+state.users[0].irisMarketId,actorName:'用户甲',accepted:true,user:true,userDecided:true,feeCents:10000}],payments:[],responses:[],applicants:[],auditions:[],shoots:[],sourceNovel:{title:b.title,chapters:IrisNovelCore.copy(b.chapters)}};s.projects.unshift(p);IrisNovelScreenCore.save(p,IrisNovelScreenCore.episode(p,IrisNovelScreenCore.fromSource(p,{title:'第一集'},5),5));openNovelStudioProject(p.id,state.users[0].irisMarketId)}`)}

